!function(){"use strict";const e=window.ChemStudyExams,t=(e,t,l,o)=>({prompt:e,options:t,correct:l,explain:o}),l=(e,l,...o)=>({method:e,input:l,...t(...o)}),o=(e,...l)=>({model:e,...t(...l)}),a=(e,t)=>({title:e,stem:t}),i=(t,l,o)=>{const a=e[t][l];return{title:o||a.title,stem:a.stem||a.prompt,source:a.source}},r={"titration-calc":{topic:"titration",name:"由滴定用量求浓度",related:["titration-error","dilution-calc"],match:"已知标准液浓度、消耗量和取样体积，所求是待测液浓度。",boundary:"题目只问某个操作使结果偏高还是偏低时，先追踪误差。",example:i("titration","example"),steps:[l("amount","0.1000 mol/L 与 22.08 mL","用掉的 NaOH 是多少？",["0.002208 mol","0.02000 mol","2.208 mol"],0,"标准液用量是 22.08 mL。0.1000×0.02208＝0.002208 mol。"),l("ratio","0.002208 mol NaOH 与 20.00 mL 醋酸","该样品的醋酸浓度是多少？",["0.02208 mol/L","0.1104 mol/L","0.2208 mol/L"],1,"醋酸与 NaOH 按 1∶1 中和。酸的物质的量除以 0.02000 L，得到 0.1104 mol/L。")],alternative:"已确认 1∶1 中和时，可直接用 c酸V酸＝c碱V碱。多元酸要先确定题设终点对应的计量比。",variants:[o("titration-calc","20.00 mL 草酸在两个酸性氢都被中和时，恰好消耗 30.00 mL、0.1000 mol/L 的 NaOH。草酸浓度是多少？",["0.1500 mol/L","0.07500 mol/L","0.3000 mol/L"],1,"每 1 mol 草酸消耗 2 mol NaOH。0.1000×30.00÷(2×20.00)＝0.07500 mol/L。"),o("titration-error","滴定管内的残水把标准 NaOH 稀释了，计算时仍用原标称浓度。盐酸浓度的报告值怎样变化？",["偏低","不变","偏高"],2,"标准液实际浓度下降，达到同一终点需要更大的体积。把大体积乘原标称浓度会高估实际物质的量。")]},"titration-error":{topic:"titration",name:"判断滴定结果偏高或偏低",related:["titration-calc","titration-endpoint"],match:"题干改变一种操作，要求判断所算浓度或纯度的偏差。",boundary:"只要求读出终点信号时，看检测判据。看到两次读数也要先问所求是什么。",example:a("尖嘴气泡影响滴定结果","用标准 NaOH 滴定一定量的盐酸。滴定前尖嘴有气泡，到终点时气泡消失，其余操作正确。按滴定管读数差算出的盐酸浓度如何变化？"),steps:[l("trace","尖嘴由有气泡变为充满碱液","读数差和实际入瓶体积相比如何？",["更小","更大","相同"],1,"有一部分碱液填进尖嘴，这部分计入读数差，却没有进入锥形瓶。"),l("ratio","读数差偏大，标准液浓度与取样体积正确","代入原计算式，酸浓度会怎样？",["偏高","偏低","不变"],0,"中和比例和取样体积固定，用偏大的碱液体积会把待测酸的量也算大。")],alternative:"可用数值对照。假设读数差 20.2 mL、实际入瓶 20.0 mL，代入同一个式子便能看出偏差方向。",variants:[o("titration-error","量取的盐酸已经全部转入锥形瓶，再加少量蒸馏水。其余操作正确。按滴定结果计算，原盐酸浓度会怎样？",["不变","偏高","偏低"],0,"加水改变了瓶内浓度，移入的 HCl 物质的量不变，达到终点所需的碱液用量也不变。"),o("titration-calc","用 0.08000 mol/L NaOH 滴定 25.00 mL 盐酸。正确读数为起始 1.20 mL、终点 21.20 mL。原盐酸浓度是多少？",["0.06784 mol/L","0.06400 mol/L","0.1000 mol/L"],1,"题目没有异常操作。碱液用量 20.00 mL，按 1∶1 算得 0.08000×20.00÷25.00＝0.06400 mol/L。")]},"titration-endpoint":{topic:"titration",name:"识别滴定终点信号",related:["titration-error","titration-calc"],match:"题目给变色、曲线或仪器读数，所求是何时到达终点或何时记录。",boundary:"终点是观察判据。题目若问读数提前或滞后会造成什么偏差，再进入误差模型。",example:i("titration","recall","酸性高锰酸钾滴定的变色"),steps:[l("signal","摇匀后的颜色和持续时间","哪个现象符合原题的终点判据？",["刚滴入时局部变红","摇匀后微红色约半分钟不褪","整瓶变深紫"],1,"局部短暂变色会随混合消失。按题意以摇匀后的浅色持续为准。")],alternative:"如果题目改给酸碱滴定曲线并问等当点，可从陡变段判断对应体积。曲线上的等当点与指示剂判据需分别读题。",variants:[o("titration-endpoint","某虚拟滴定的终点规定为「整体浅粉色保持 30 秒」。10.4 mL 时局部变粉，10.6 mL 时浅粉保持 8 秒，10.8 mL 时满足规定。何时记录？",["10.4 mL","10.8 mL","10.6 mL"],1,"只有 10.8 mL 同时满足颜色、整体混匀和持续时间的条件。"),o("titration-error","用标准碱滴定定量盐酸。达到题设终点后又多滴了碱，才记末读数。报告浓度怎样？",["偏高","偏低","不变"],0,"延后记录使读数差偏大。用该读数计算会高估用于中和的碱液量。")]},"net-ionic":{topic:"ions",name:"写净离子方程式",related:["ion-coexist","redox-electrons"],match:"明确要写或核对净离子式，关键是反应前后真实存在的微粒。",boundary:"共存题以能否同处为结论。若所求是电子数，则以电子守恒为主考法。",example:i("ions","example"),steps:[l("conditions","题干给出足量 CO₂","最终写哪种含碳微粒？",["CO₃²⁻","HCO₃⁻","C₂O₄²⁻"],1,"在这道题的足量条件下，含碳产物按 HCO₃⁻ 写。"),l("ions","ClO⁻、CO₂、H₂O、Ca²⁺","哪条式子表示净反应？",["ClO⁻＋CO₂＋H₂O → HClO＋HCO₃⁻","Ca²⁺＋CO₂ → CaCO₃↓","ClO⁻＋CO₂ → Cl⁻＋CO₃²⁻"],0,"ClO⁻ 接受 H⁺ 形成弱酸 HClO。Ca²⁺ 在两侧相同，可消去，所写式子的总电荷均为 −1。")],alternative:"能先确定产物时，也可写分子式、拆开两边在水中完全电离的物质，再逐项约去旁观离子。",variants:[o("net-ionic","用 OH⁻ 中和醋酸，哪一条式子正确表示净反应？",["H⁺＋OH⁻ → H₂O","CH₃COOH＋OH⁻ → CH₃COO⁻＋H₂O","CH₃COOH → CH₃COO⁻＋OH⁻"],1,"醋酸是弱电解质，反应物端保留分子式，再检查原子和电荷。"),o("ion-coexist","在强酸性溶液中，哪组离子能大量共存？",["Na⁺、CO₃²⁻","K⁺、OH⁻","Na⁺、NO₃⁻"],2,"题干提供 H⁺。它会消耗 CO₃²⁻ 和 OH⁻，在该题条件下可与 Na⁺、NO₃⁻ 大量共存。")]},"ion-coexist":{topic:"ions",name:"按环境判断离子共存",related:["net-ionic","redox-electrons"],match:"要筛选一组能在指定酸碱性、颜色等条件下大量共存的离子。",boundary:"若要交付的是净离子式，筛出的反应还要写成守恒的式子。",example:a("无色强碱性溶液中的离子","在无色强碱性溶液中，比较 Na⁺、NO₃⁻；Mg²⁺、Cl⁻；K⁺、MnO₄⁻ 这三组离子，哪组能大量共存？"),steps:[l("conditions","无色、强碱性","要把哪个隐含离子加入检查？",["H⁺","OH⁻","Cl⁻"],1,"强碱性对应足量 OH⁻，无色还要求排除明显着色的离子。"),l("ions","三组离子、OH⁻ 和无色要求","哪组通过两项检查？",["Mg²⁺、Cl⁻","K⁺、MnO₄⁻","Na⁺、NO₃⁻"],2,"Mg²⁺ 会生成氢氧化物沉淀，MnO₄⁻ 使溶液显色，Na⁺ 与 NO₃⁻ 符合题设。")],alternative:"可逐组选反例。先看颜色或题设直接排除的组，余下每组找一个能生成沉淀、气体、弱电解质或发生氧化还原的离子组合。",variants:[o("ion-coexist","在无色强酸性溶液中，下面哪组离子能大量共存？",["NH₄⁺、NO₃⁻","K⁺、HCO₃⁻","Na⁺、Fe³⁺"],0,"NH₄⁺、NO₃⁻ 符合。HCO₃⁻ 遇 H⁺ 转化为 CO₂ 和水，Fe³⁺ 溶液显色。"),o("net-ionic","混合含 Ba²⁺ 的溶液和含 SO₄²⁻ 的溶液，要求写生成沉淀的净离子式。哪条正确？",["Ba²⁺＋SO₄²⁻ → BaSO₄↓","Ba²⁺＋2SO₄²⁻ → Ba(SO₄)₂↓","Na⁺＋Cl⁻ → NaCl↓"],0,"Ba²⁺ 与 SO₄²⁻ 按 1∶1 形成沉淀，两边总电荷都是零。")]},"redox-electrons":{topic:"redox",name:"用电子守恒求用量或价态",related:["net-ionic","cell-poles"],match:"给出变价物质或产物，要求求反应比例、转移电子量或未知价态。",boundary:"出现电池也要看所求。只求正负极走电极判断，求电子量再用守恒。",example:i("redox","example"),steps:[l("electrons","酸性组 0.001 mol I⁻，Mn 由 +7 降到 +2","酸性组消耗 KMnO₄ 的 n 是多少？",["0.005 mol","0.001 mol","0.0002 mol"],2,"每个 I⁻ 失 1 个电子，每个 Mn 得 5 个。5n＝0.001 mol。"),l("balance","中性组 Mn 由 +7 降到 +4，KMnO₄ 用量 10n","由中性组推出 IOₓ⁻ 中 x 为多少？",["2","3","4"],1,"中性组共得 3×10n＝0.006 mol 电子，每个 I⁻ 失 6 个，碘升至 +5。5−2x＝−1，得 x＝3。")],alternative:"如果两侧产物已知，也可把氧化、还原各写成半反应，按电子的最小公倍数相加，再读计量系数。",variants:[o("redox-electrons","在给定的反应里，0.20 mol Zn 全部变成 Zn²⁺，Ag⁺ 是唯一接受电子的微粒且变成 Ag。消耗多少 Ag⁺？",["0.10 mol","0.20 mol","0.40 mol"],2,"Zn 每摩尔失 2 mol 电子，Ag⁺ 每摩尔得 1 mol 电子，所以消耗 0.40 mol。"),o("redox-electrons","题设过氧化氢仅被氧化成 O₂。每 1 mol H₂O₂ 失去多少电子？",["1 mol","2 mol","4 mol"],1,"过氧化氢的每个 O 从 −1 到 0，每个分子有两个 O，合计失 2 mol 电子。")]},"dilution-calc":{topic:"dilution",name:"按溶质守恒算稀释量",related:["solution-prep","titration-calc"],match:"同一种溶质只被稀释，题目给浓度和体积，要求取用量或终浓度。",boundary:"有化学反应时，先按方程式换算。定容、损失或器材问题看配液条件。",example:i("dilution","recall","从浓醋酸溶液配制指定浓度"),steps:[l("trace","浓溶液被水稀释","被取出的这份醋酸，哪一个量在稀释前后相同？",["浓度","体积","醋酸的物质的量"],2,"题目假定只加水，没有溶质损失。浓度和体积会变，所取醋酸的量保持不变。"),l("amount","5 mol/L 配出 250 mL、0.1 mol/L","原溶液要取多少？",["50 mL","5.0 mL","12.5 mL"],1,"c₁V₁＝c₂V₂，同用 mL 可得到 V₁＝0.1×250÷5＝5.0 mL。")],alternative:"先算目标溶液需要 0.025 mol 醋酸，再用 n÷c原 求取样体积。这个写法便于分别核对单位。",variants:[o("dilution-calc","取 10.0 mL、0.400 mol/L 溶液，稀释到 80.0 mL，溶质没有损失。终浓度是多少？",["0.0444 mol/L","0.0500 mol/L","0.400 mol/L"],1,"80.0 mL 是最终总体积。0.400×10.0÷80.0＝0.0500 mol/L。"),o("solution-prep","按标准操作配溶液时，最后加水超过容量瓶刻度线。溶质未损失。实际浓度相对目标值怎样？",["偏高","偏低","相同"],1,"n 保持，实际 V 增大，所以实际 c＝n/V 变小。")]},"solution-prep":{topic:"dilution",name:"判断容量瓶操作与配液误差",related:["dilution-calc","titration-error"],match:"题干围绕量取、转移、定容或混匀，要求说明操作、器材或配液偏差。",boundary:"目标是求浓液取用量且溶质守恒时，用稀释计算。若还问滴定结果，再接滴定模型。",example:i("dilution","example"),steps:[l("trace","称取的样品、附着在器皿的溶液","把洗液转入容量瓶主要保持哪个量？",["称取样品进入容量瓶的物质的量","容量瓶的刻度","最终水的物质的量"],0,"洗液带回残留溶质，避免实际转入量比称取量小。"),l("conditions","已经定容，瓶内尚未混匀","哪一步能让取出的样品有代表性？",["再加水","盖好瓶塞并倒转摇匀","取上层溶液"],1,"定容决定总体积，混匀才使各处浓度相同。")],alternative:"误差题可画两栏分别记录 n 和 V。选择器材时先看目标体积与精度，再核对所选器材的刻度。",variants:[o("solution-prep","转移已溶解的溶液时有少量溅出，后来仍定容到刻度。成品浓度怎样？",["偏低","相同","偏高"],0,"溅出使 n 减小。最后 V 仍为规定值，所以 c 偏低。"),o("solution-prep","取两份物质的量相同的溶质，分别在 100 mL 和 250 mL 的容量瓶中配成溶液。哪一瓶浓度更大？",["250 mL","两者相同","100 mL"],2,"溶质的量相同，100 mL 瓶的最终体积小，浓度更大。")]},"cell-poles":{topic:"cell",name:"判电极、电子流向和半反应",related:["redox-electrons","net-ionic"],match:"问电极发生什么反应、哪一极、电子或题设离子向哪边移动。",boundary:"充电与放电要先分清。只问转移多少电子时，用得失电子守恒作主模型。",example:i("cell","example"),steps:[l("electrode","放电时 Zn → Zn²⁺＋2e⁻","哪侧是放电负极？",["V₂O₅ 侧","Zn 侧","两侧都不是"],1,"Zn 失电子、发生氧化，是放电负极。外电路电子从 Zn 侧流向接受电子的一侧。"),l("conditions","同一可逆电池进入充电阶段","充电总反应与放电总反应是什么关系？",["方向相反","方向相同","只改电子数"],0,"题设可逆充放电。整个反应的反应物和产物对调，反应方向反转。")],alternative:"若题目直接给半反应，可先找 e⁻ 所在一侧。电子写在产物端的是氧化，写在反应物端的是还原。",variants:[o("cell-poles","锌铜原电池放电，半反应为 Zn → Zn²⁺＋2e⁻ 和 Cu²⁺＋2e⁻ → Cu。外导线中电子流向如何？",["铜到锌","从电解液流向导线","锌到铜"],2,"电子从发生氧化的锌负极，经外导线到发生还原的铜正极。"),o("redox-electrons","某锌电池的负极已判定是 Zn。放电时 0.030 mol Zn 变成 Zn²⁺，转移多少 mol 电子？",["0.060 mol","0.030 mol","0.015 mol"],0,"电极已经确定，所求是电子量。每个 Zn 失 2 个电子，所以是 0.060 mol。")]},"equilibrium-q":{topic:"equilibrium",name:"恒温比较 Q 与 K 判移动方向",related:["equilibrium-temp","dilution-calc"],match:"温度固定，题目给当前组成或扰动，要求判断反应净向哪边。",boundary:"温度变化时应换用新温度的 K。仅知道升温或降温时，可先用热效应判断 K 的变化。",example:i("equilibrium","recall","由反应商判断平衡移动"),steps:[l("quotient","同一温度，题给 Q＜K","此时相对平衡，哪侧的商项偏小？",["产物项与反应物项之比","反应物项与产物项之比","无法比较"],0,"Q 按方程式以产物项为分子，当前比值小于平衡比值。"),l("trace","当前 Q 需要增大到 K","净反应朝哪边？",["逆向","已平衡","正向"],2,"正向消耗反应物并生成产物，使 Q 增大。")],alternative:"若在原平衡基础上只改变一种反应物或产物的浓度，可直接判断 Q 的变化方向，再和原 K 比。",variants:[o("equilibrium-q","恒温下 A(g) ⇌ 2B(g)。按题设的浓度数值计算，K＝4，当前 [A]＝0.50、[B]＝1.50。净反应向哪边？",["正向","逆向","已经平衡"],1,"Q＝1.50²÷0.50＝4.5＞4，应逆向消耗 B，使 Q 下降。"),o("equilibrium-temp","同一个反应升温后，测得瞬时 Q 仍等于旧温度的 K。已知正反应吸热。新 K 以及净反应方向如何？",["K 增大，正向","K 减小，逆向","K 不变，已平衡"],0,"先用热效应判断新 K 大于旧 K。已知瞬时 Q＝旧 K，故 Q＜新 K。")]},"equilibrium-temp":{topic:"equilibrium",name:"由温度和热效应判断 K",related:["equilibrium-q","hess-path"],match:"给正反应 ΔH 与温度变化，问新平衡倾向或 K 的增减。",boundary:"恒温改浓度、分压或加入催化剂时，给定反应的 K 保持原值。",example:i("equilibrium","example"),steps:[l("heat","给定方向 ΔH＝−114.4 kJ/mol","升温更有利于哪一方向？",["放热的正向","吸热的逆向","两边均无影响"],1,"题给正反应放热。逆向吸热，升温有利于逆向。"),l("quotient","升温后平衡相对偏向反应物","按原方程式写的 K 如何变化？",["增大","不变","减小"],2,"同一反应写法下，升温使放热反应的 K 减小。")],alternative:"把热量放到放热反应的产物一侧，用增热时偏向消耗热量的一侧来判断。这个类比只用来判断方向。",variants:[o("equilibrium-temp","A(g) ⇌ B(g) 的正反应吸热。原来已平衡，在恒容容器中降温。新 K 以及净反应方向如何？",["K 增大，正向","K 减小，逆向","K 不变，已平衡"],1,"降温有利于放热的逆反应。新 K 减小，瞬时浓度未变，Q 大于新 K。"),o("equilibrium-q","恒温恒容、已平衡的 A(g) ⇌ B(g) 体系中，加入少量 A。K 和净反应方向如何？",["K 减小，逆向","K 不变，正向","K 增大，正向"],1,"温度没变，K 保持原值。加入 A 后分母增大，Q 下降，体系净向正向进行。")]},"molecular-shape":{topic:"polarity",name:"由电子域判断构型与键角",related:["molecular-polarity","ion-coexist"],match:"题目问原子在空间中的排布、电子域或键角，先看中心原子与孤电子对。",boundary:"若最终问分子整体是否有极性，构型是中间结果，还要看键偶极。",example:i("polarity","recall","叠氮离子的空间构型"),steps:[l("shape","按高中常用 Lewis 结构处理 N₃⁻","中心 N 有几个成键方向？",["1 个","2 个","3 个"],1,"中心 N 连接两个端 N。无论一个方向有多少重键，都只记一个成键电子域。"),l("shape","中心 N 有两个成键域，无孤电子域","三个原子怎么排列？",["直线形","V 形","三角锥形"],0,"两个电子域相互远离，夹角按 180° 处理。")],alternative:"若已知 Lewis 结构，可先写 AXₘEₙ，再查对应构型。遇到多重键时仍按成键方向计数。",variants:[o("molecular-shape","H₂S 的中心 S 有两个成键方向、两对孤电子。只看三个原子的位置，是什么构型？",["直线形","V 形","正四面体形"],1,"四个电子域里有两个孤电子域。构型描述的是原子位置，所以是 V 形。"),o("molecular-polarity","给出 CO₂ 的分子构型为直线形，两根 C＝O 键相同。问分子有无极性，正确理由是什么？",["有，两根键都有极性","无，两个等大反向的键偶极抵消","无，每根 C＝O 键都无极性"],1,"分子整体由键偶极的合量决定。两根键各有极性，合量为零。")]},"molecular-polarity":{topic:"polarity",name:"由构型与键偶极判断分子极性",related:["molecular-shape","net-ionic"],match:"所求是分子整体的极性，必须结合实际构型和各键偶极。",boundary:"只问构型或键角时，判断电子域和孤电子对即可。",example:i("polarity","example"),steps:[l("shape","NH₃ 和 ND₃ 都有 3 个成键域和 1 对孤电子","两者的分子构型是什么？",["平面三角形","直线形","三角锥形"],2,"孤电子对不算作原子位置，中心 N 与三个外围原子呈三角锥形。"),l("dipoles","两种分子都为三角锥形","沿三角锥轴线的键偶极分量能否全部抵消？",["能，两种都无极性","不能，两种都有极性","只有 ND₃ 能抵消"],1,"三根键的横向分量对称抵消，轴向分量仍有合量。")],alternative:"像 CO₂、BF₃ 这样由相同键对称排布的分子，可用对称性快速判断。外围原子不全相同时，重新检查各键偶极。",variants:[o("molecular-polarity","BF₃ 是平面三角形，三个 B—F 键相同。BF₃ 是极性分子吗？",["是，单个键有极性","是，平面三角形有合量","否，三个键偶极相互抵消"],2,"三个等大的键偶极在同一平面按 120° 排布，合量为零。"),o("molecular-polarity","CH₄ 和 CH₂Cl₂ 的中心碳周围均呈四面体排布。哪一个分子有极性？",["只有 CH₂Cl₂","两个都有","两个都没有"],0,"CH₄ 的四个等价键对称抵消。CH₂Cl₂ 的两类键不同，四面体排布下偶极合量不为零。")]},"ester-workup":{topic:"ester",name:"按官能团判断酯化产物中的杂质去向",related:["net-ionic","equilibrium-q"],match:"给出有机反应产物和杂质，要求根据官能团或分离条件解释杂质怎样被去掉。",boundary:"若问产率怎样变化，转到平衡模型。若只求反应焓，按热化学路径计算。",example:i("ester","practice","从酯化产物中除去残留乙酸"),steps:[l("conditions","乙酸乙酯、残留乙酸和碳酸钠","哪种成分的羧基能提供 H⁺ 被中和？",["乙酸","乙酸乙酯","二者都有羧基"],0,"乙酸有羧基。乙酸乙酯的酯基没有羧酸的酸性氢。"),l("ions","羧酸与碳酸根发生酸碱反应","乙酸主要转变为什么形式？",["乙酸盐，留在水相","更多乙酸乙酯","乙醇，进入气相"],0,"乙酸被中和成乙酸根，可随水相分开。")],alternative:"也可对照处理前后的官能团，写 2CH₃COOH＋CO₃²⁻ → 2CH₃COO⁻＋CO₂＋H₂O，再根据乙酸盐的水溶性判断去向。",variants:[o("ester-workup","某酯化产物中混有少量丙酸，题设用碳酸氢钠处理后分相。丙酸主要以哪种形式进入水相？",["丙醇","丙酸钠","原来的酯"],1,"丙酸的羧基发生中和，形成水溶性的丙酸盐。"),o("equilibrium-q","同温下，某羧酸与醇的酯化已经平衡。题设能选择性减少产物水的有效浓度。平衡怎样变化？",["逆向","正向","不变"],1,"移去水使产物项下降，Q 低于 K，体系净向生成酯和水的方向移动。")]},"hess-path":{topic:"ester",place:{book:"reactions",chapter:0,point:"热化学方程式与盖斯定律"},name:"拼合热化学方程式求焓变",related:["equilibrium-temp","ester-workup"],match:"给多条反应焓或燃烧焓，要求得到另一个指定反应的 ΔH。",boundary:"只问温度变化如何影响平衡时，使用给定 ΔH 的正负判断。",example:i("ester","example"),steps:[l("energy","目标为乙酸＋乙醇 → 乙酸乙酯＋水","哪两条路线能放在同一个能量循环里？",["分别燃烧两种反应物；或先酯化再燃烧酯","分别只燃烧乙酸；或只燃烧乙醇","单独燃烧水；或燃烧乙酸乙酯"],0,"第一组两条路径完全燃烧后的产物组成和物态相同。"),l("energy","反应物燃烧焓 −874、−1367，酯燃烧焓 −2238 kJ/mol","目标 ΔH 是多少？",["+3 kJ/mol","−4479 kJ/mol","−3 kJ/mol"],2,"酯化焓＋酯燃烧焓＝反应物燃烧焓之和。得到 −874−1367−(−2238)＝−3 kJ/mol。")],alternative:"也可以逐条写出热化学方程式，把酯的燃烧反应反向后，与酸、醇的燃烧方程式相加。最后检查水的系数和物态。",variants:[o("hess-path","同一物态下 A→B 的 ΔH＝−50 kJ/mol，C→B 的 ΔH＝−20 kJ/mol。求 A→C 的 ΔH。",["−30 kJ/mol","−70 kJ/mol","+30 kJ/mol"],0,"把 C→B 反向得到 B→C，ΔH＝+20 kJ/mol。与 A→B 相加得 −30 kJ/mol。"),o("hess-path","已知 A→B 的 ΔH＝+25 kJ/mol，B→C 的 ΔH＝−10 kJ/mol。按题设计量写成 2C→2A，ΔH 是多少？",["−15 kJ/mol","+30 kJ/mol","−30 kJ/mol"],2,"A→C 为 +15 kJ/mol。反向变为 −15 kJ/mol，再按方程式倍乘得到 −30 kJ/mol。")]}},m=(e,t,o,...a)=>({part:e,...l(r[e].steps[t].method,o,...a)}),n={"titration-combo":{topic:"titration",name:"先算滴定结果，再判断误差",parts:["titration-calc","titration-error"],related:["titration-calc","titration-error"],match:"一题既要算报告浓度，又要判断同一读数受操作影响产生的误差。",boundary:"只问浓度或偏差时，按所求选择单个考法。",example:a("记录表上的浓度可信么？","取 20.00 mL 盐酸，用 0.1000 mol/L NaOH 滴定。读数差为 20.40 mL，其中 0.40 mL 填入原先有气泡的尖嘴。先算按记录表得到的浓度，再算实际浓度。"),steps:[m("titration-calc",1,"表上的 20.40 mL、取样 20.00 mL、1∶1 中和","按记录表计算，报告浓度是多少？",["0.1000 mol/L","0.1020 mol/L","0.0980 mol/L"],1,"用原记录计算 0.1000×20.40÷20.00＝0.1020 mol/L。这个数交给下一步做比较。"),m("titration-error",0,"报告 0.1020 mol/L，其中 0.40 mL 未入瓶","按实际入瓶体积算，浓度和偏差是什么？",["0.1000 mol/L，报告偏高","0.1020 mol/L，报告准确","0.1040 mol/L，报告偏低"],0,"实际入瓶为 20.00 mL。实际浓度是 0.1000 mol/L，报告高了 0.0020 mol/L。")],alternative:"也可先求报告值与实际值之比。其他条件固定时，浓度比等于读数差与实际入瓶体积之比。",variants:[o("titration-combo","10.00 mL 盐酸用 0.1000 mol/L NaOH 滴定。实际 9.80 mL 已到终点，多滴 0.20 mL 后才记录。报告浓度与实际浓度分别为多少？",["0.09800 和 0.1000 mol/L","0.1000 和 0.09800 mol/L","两者都为 0.1000 mol/L"],1,"报告用 10.00 mL，实际用 9.80 mL。分别代入同一中和关系即可。"),o("titration-error","固定样品正常滴定到终点。记录员把末读数抄大了 0.20 mL，初读数正确。题目只问报告浓度偏差。结论是什么？",["偏低","不变","偏高"],2,"只需定位读数差被抄大，再看浓度式的分子随读数差增大。")]},"polarity-combo":{topic:"polarity",name:"先判构型，再用构型判极性",parts:["molecular-shape","molecular-polarity"],related:["molecular-shape","molecular-polarity"],match:"题目分别要求写分子的空间构型和整体极性，前一个结果用于后一个。",boundary:"构型已经给出并且只问整体极性时，可以直接用键偶极。",example:a("水分子的构型与极性","H₂O 的中心 O 有两个成键方向、两对孤电子。依次判断分子构型和整体极性。"),steps:[m("molecular-shape",0,"两个成键方向和两对孤电子","H₂O 的分子构型是什么？",["正四面体形","直线形","V 形"],2,"构型只看原子位置，两个成键方向形成 V 形。把这个夹角交给下一步。"),m("molecular-polarity",1,"V 形构型和两根 O—H 键","键偶极的合量怎样？",["为零，H₂O 无极性","不为零，H₂O 有极性","两根键都无偶极"],1,"V 形的两根键偶极大小相同，但方向不相反，合量不为零。")],alternative:"也可沿两键的角平分线分解向量。垂直分量抵消，平行分量相加，便于核对极性的判断。",variants:[o("polarity-combo","BeCl₂ 气相单分子中，中心 Be 有两个成键方向、无孤电子对。题目同时问分子构型和极性。选出正确组合。",["V 形，有极性","直线形，无极性","直线形，有极性"],1,"两个电子域给直线形，两根等大的键偶极反向抵消。"),o("molecular-polarity","题目已给出 CCl₄ 的正四面体构型，四根 C—Cl 键相同。只问分子是否有极性。",["有，因为四个键有极性","没有，因为四个偶极对称抵消","有，因为不是平面构型"],1,"构型已知。正四面体的四个等大、对称排布的偶极合量为零。")]}},c=(e,...l)=>({goal:e,...t(...l)}),s={"titration-calc":c("分清标准液用量和样品体积，知道为什么先算物质的量。","要求标准液的物质的量，标准液浓度应和哪个体积配在一起？",["样品体积","实际消耗的标准液体积","混合液总体积"],1,"算的是标准液中溶质的量，所以浓度和体积都要取自标准液。"),"titration-error":c("找出异常操作改变了哪个量，再沿算式判断结果的方向。","计算式中，标准液体积在分子上。只把这个体积读大了，报告值会怎样？",["变小","保持原值","变大"],2,"其他量固定时，分子变大会使计算结果变大。先找出读数变化，再看它在算式里的位置。"),"titration-endpoint":c("分清短暂出现的信号和符合判据的终点信号。","某滴定用颜色持续来判终点，刚滴入时局部变色，摇匀后完全消失。接下来怎样判断？",["把这次局部变色记作终点","继续观察是否出现符合判据的持久变色","等到颜色很深才记录"],1,"题设要求颜色持续。摇匀后颜色消失，说明这次局部变色还未达到终点判据。"),"net-ionic":c("弄清哪些微粒要保留，哪些可以在离子方程式两边消去。","某种离子在完整离子式两边都存在，种类和数目相同。写净离子式时怎样处理？",["两边一起消去","只从反应物一侧消去","写成气体"],0,"这种离子没有参与净反应，两边同时消去后，式子的原子数和电荷仍然守恒。"),"ion-coexist":c("把题干提供的酸碱条件也放进共存检查。","题目说溶液呈强酸性，检查离子能否共存时，哪种离子要一起考虑？",["OH⁻","Na⁺","H⁺"],2,"强酸性意味着有较多 H⁺。即使选项没有写出 H⁺，也要检查其他离子是否会与它反应。"),"redox-electrons":c("把化合价的升降和得失电子连起来。","在同一个氧化还原反应中，氧化一方失去的电子总量和还原一方得到的总量有什么关系？",["失去的总量较多","两个总量相等","两个总量无关"],1,"氧化还原中的电子由失去电子的一方转移给得到电子的一方，两个总量必须相等。"),"dilution-calc":c("理解稀释前后哪个量保持，分清加水量和稀释后的总体积。","从浓溶液取样，加水配成指定体积。用浓度乘体积求稀释后溶质的量，应取哪个体积？",["加水前的取样体积","加入的水的体积","配成后的总体积"],2,"稀释后的浓度对应配成后的整个溶液，两者配对相乘才是稀释后的溶质物质的量。"),"solution-prep":c("把转移、定容和混匀分别对应到溶质的量、总体积和取样。","溶质已经全部转进容量瓶，下一步定容主要确定什么？",["加入水的物质的量","溶液最终总体积","溶质的摩尔质量"],1,"刻度对应配成后的溶液总体积。溶质已经转入，定容这一步要控制的是体积。"),"cell-poles":c("分清电子走的外电路和离子移动的电解质。","原电池放电时，外导线上输送电荷的微粒是什么？",["电子","溶液中的阳离子","溶液中的阴离子"],0,"电子沿外导线移动。电解质内部的电荷输送靠离子移动。"),"equilibrium-q":c("读懂 Q 和 K 分别代表什么，以及比较前要核对的条件。","要比较当前的 Q 与 K，应先核对哪一项？",["只要两者数值接近即可","方程式的写法一致，并使用当前温度的 K","把 K 按反应时间换算"],1,"Q 与 K 必须按同一个反应方向和计量式写。K 还对应具体温度。"),"equilibrium-temp":c("把温度改变、吸放热方向和平衡常数的变化连起来。","题设只加催化剂，温度保持不变。这个反应的平衡常数怎样变化？",["增大","减小","保持原值"],2,"催化剂能改变达到平衡的速度。给定反应在同温下的平衡常数保持原值。"),"molecular-shape":c("先数电子域，再看构型图里哪些位置由原子占据。","画分子构型时，中心原子的孤电子对怎样考虑？",["影响原子排布，画构型时只标实际原子","和一个外围原子画在一起","直接当作一根额外的键"],0,"孤电子对会影响其他电子域的排布。分子构型描述的是原子的位置。"),"molecular-polarity":c("用键偶极的方向和大小解释它们能不能抵消。","两个键偶极方向相反，但大小不同。叠加后的合量怎样？",["一定为零","大小不同，仍有合量","只有在同一直线上才有合量"],1,"方向相反的两个偶极只有大小也相等时才能完全抵消。"),"ester-workup":c("理解酸碱反应怎样改变杂质在两相里的去向。","要把羧酸杂质转到水相，酸碱处理主要让羧酸变成哪种形式？",["更难溶的中性酯","原来的羧酸分子","更易留在水相的羧酸盐"],2,"羧酸与碱反应形成羧酸盐。生成的离子更容易留在水相，可以和酯分开。"),"hess-path":{...c("热化学方程式可以按目标反应拼起来，焓变也要跟着调整。","把一条热化学方程式反向写，其他条件和计量系数保持一致，ΔH 怎样变？",["大小保持，正负号反过来","数值和符号都保持","直接乘二"],0,"反向交换了起点和终点，焓变的大小相同，方向相反。"),reading:"从反应物到生成物，可以走不同的反应路径。起点和终点相同时，整条路径的焓变也相同。盖斯定律可以帮我们把几条已知反应拼成目标反应。"},"titration-combo":c("知道滴定的报告值和实际值分别用哪个体积，再比较偏差。","同一份滴定样品的报告值用了读数差。重新求实际值时，应换成哪个量？",["样品体积","实际进入锥形瓶的标准液体积","滴定管的总容量"],1,"报告值沿用记录，实际值对应真正进入锥形瓶并参与反应的标准液体积。"),"polarity-combo":c("先确定原子怎样排列，再用这个排布判断键偶极能不能抵消。","构型和整体极性都未知时，哪一步能给判断键偶极方向提供依据？",["只统计键的总数","先假定每条键都能抵消","先判断分子实际构型"],2,"原子的排布决定各键的空间方向。先有构型，才能比较键偶极的方向。")},p={"titration-calc":[/滴定|滴定管/,/求.{0,18}(浓度|纯度|含量)|(?:浓度|纯度|含量).{0,4}(多少|为\s*[？?])/],"titration-error":[/滴定|滴定管/,/偏高|偏低|误差|结果.{0,6}影响/],"titration-endpoint":[/滴定|指示剂/,/判断.{0,5}终点|(?:何时|什么时候).{0,6}(读数|记录)|哪个现象.{0,6}终点/],"net-ionic":[/离子(?:方程)?式/,/(?:写出|写下|书写|列出|补全|配平|判断).{0,14}离子(?:方程)?式|下列[^。；，]{0,12}离子(?:方程)?式[^。；，]{0,12}(?:正确|错误)|离子(?:方程)?式(?:怎么写|如何写|是否正确)/],"ion-coexist":[/溶液|离子|酸性|碱性/,/共存/],"redox-electrons":[/电子|化合价|价态/,/求.{0,14}(电子|价态|用量)|转移.{0,10}(多少|几|电子的量)|得失.{0,6}电子/],"dilution-calc":[/稀释|加水配成|浓溶液/,/求.{0,14}(体积|浓度)|(?:体积|浓度).{0,4}(多少|为\s*[？?])/],"solution-prep":[/配制|容量瓶|定容/,/偏高|偏低|操作|器材|误差|洗液|摇匀/],"cell-poles":[/原电池|放电|充电|盐桥/,/正极|负极|电极反应|电子流向|迁移方向/],"equilibrium-q":[/平衡|反应商|恒温/,/向哪|净反应|平衡移动|正向|逆向/],"equilibrium-temp":[/升温|降温|温度|吸热|放热/,/平衡常数|新\s*K|\bK\s*(?:增|减|如何|怎样)/],"molecular-shape":[/分子|中心原子|电子域|孤电子|V\s*S\s*[EB]\s*P\s*R|V\s*E\s*S\s*P\s*R/i,/构型.{0,5}(为|是|什么)|(?:求|判|比较).{0,8}(构型|键角)|空间(?:构型|结构)|V\s*S\s*[EB]\s*P\s*R|V\s*E\s*S\s*P\s*R/i],"molecular-polarity":[/分子|键偶极/,/是否.{0,4}极性|有无极性|极性分子|极性.{0,5}(?:如何|怎样)/],"ester-workup":[/酯化|乙酸乙酯|羧酸/,/除去|杂质|分离|水相|馏出物/],"hess-path":[/燃烧焓|燃烧热|热化学|盖斯|ΔH/i,/(?:求|计算).{0,20}(?:焓变|ΔH)|焓变.{0,6}(?:为|等于|多少)/i]};window.ChemMethodCatalog={methods:{conditions:{name:"翻译题设条件",rule:"圈出介质、过量、温度、放电等限定词，写出它们对微粒或过程的影响。"},amount:{name:"换算物质的量",rule:"同一种物质的浓度与体积配对。由 n＝cV 或 n＝m/M 换算，体积换成 L。"},ratio:{name:"按计量关系换算",rule:"从配平反应式读出两种物质的量之比，再换算题目所求的量。"},trace:{name:"追踪一个量的变化",rule:"先列正确操作下的关系，再定位哪一个量实际改变，其他量逐个核对。"},ions:{name:"保留实际参与的微粒",rule:"根据水溶液中微粒的存在形式写反应，消去旁观离子，保留弱电解质、沉淀和气体。"},balance:{name:"核对原子数与电荷",rule:"对照式子两边的每种原子数和总电荷，也可用离子总电荷反推未知价态。"},electrons:{name:"计算得失电子",rule:"每个变价原子的价态变化乘原子数和物质的量，失电子总量等于得电子总量。"},electrode:{name:"定位氧化与还原",rule:"写半反应或看电子出现在哪一侧。放电时负极氧化、正极还原。"},quotient:{name:"比较 Q 与 K",rule:"按同一方程式写 Q，省去纯固体和纯液体项，与当前温度下的 K 比较。"},heat:{name:"用热效应判方向",rule:"按题目所写方向读 ΔH，升温有利于吸热方向，降温有利于放热方向。"},shape:{name:"由电子域还原构型",rule:"中心原子的每个成键方向算一个电子域，另计孤电子对。分子构型只看原子位置。"},dipoles:{name:"叠加键偶极",rule:"先画分子的实际构型，再按键偶极的方向和大小判断合量是否为零。"},energy:{name:"拼合反应路径",rule:"热化学方程式反向则 ΔH 变号，整体倍乘则 ΔH 同倍乘。相加后核对净反应和物态。"},signal:{name:"读取终点证据",rule:"先认清题设采用的检测信号，再区分瞬间变化与满足判据的变化。"}},models:r,combinations:n,examModels:{titration:{example:["titration-calc"],practice:["titration-error","solution-prep"],recall:["titration-endpoint"]},ions:{example:["net-ionic"],practice:["net-ionic","redox-electrons"],recall:["net-ionic"]},redox:{example:["redox-electrons"],practice:["redox-electrons"],recall:["redox-electrons"]},dilution:{example:["solution-prep"],practice:["solution-prep"],recall:["dilution-calc"]},cell:{example:["cell-poles"],practice:["redox-electrons","cell-poles"],recall:["cell-poles","net-ionic"]},equilibrium:{example:["equilibrium-temp"],practice:["equilibrium-q"],recall:["equilibrium-q"]},polarity:{example:["molecular-polarity","molecular-shape"],practice:["molecular-shape"],recall:["molecular-shape"]},ester:{example:["hess-path"],practice:["ester-workup"],recall:["equilibrium-q"]}},lessonChecks:s,matchPrompt:function(e){const t=e.normalize("NFKC").split(/(?:^|\s)[A-H][.、:)]\s*/)[0].replace(/\s+/g," ");return Object.entries(p).filter(([,e])=>e.every(e=>e.test(t))).map(([e])=>e)}}}();
